mutations.after:
const candidates = tags
  .filter((tag) => RELEASE_TAG_PATTERN.test(tag))
  .sort((a, b) => {
    const [xa, ya, za] = a.slice(1).split(".").map(Number);
    const [xb, yb, zb] = b.slice(1).split(".").map(Number);
    return xb - xa || yb - ya || zb - za;
  });

mutations.before:
try {
  target = await targetFor(entry);
} catch (error) {
  stopped = `the ${entry.side ?? 'head'} app could not be installed for launch ${position}: ${firstLine(error)}`;
  break;
}

try {
  await target.terminate();
} catch (error) {
  stopped = `the app could not be stopped after launch ${position}: ${firstLine(error)}`;
  break;
}
